<template><span class="inline-flex rounded-full px-2 py-1 text-xs font-medium" :class="tone">{{ value }}</span></template><script setup lang="ts">import { computed } from 'vue'; const props = defineProps<{ value: string }>(); const tone = computed(() => ['healthy','passed','active','resolved'].includes(props.value) ? 'bg-emerald-100 text-emerald-700' : ['blocked','open','degraded','stale'].includes(props.value) ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700');</script>
